import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.xeBd2WE1.js";const m=JSON.parse('{"title":"AI 动态 · 2026-10-08","description":"","frontmatter":{"title":"AI 动态 · 2026-10-08","date":"2026-10-08T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-10/ai-news-2026-10-08.md","filePath":"news/2026-10/ai-news-2026-10-08.md","lastUpdated":null}'),r={name:"news/2026-10/ai-news-2026-10-08.md"};function i(o,e,l,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-10-08" tabindex="-1">AI 动态 · 2026-10-08 <a class="header-anchor" href="#ai-动态-·-2026-10-08" aria-label="Permalink to &quot;AI 动态 · 2026-10-08&quot;">​</a></h1><blockquote><p>截至 2026-10-08。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="manus-与-meta-分拆后首轮融资超-5-亿美元" tabindex="-1">Manus 与 Meta 分拆后首轮融资超 5 亿美元 <a class="header-anchor" href="#manus-与-meta-分拆后首轮融资超-5-亿美元" aria-label="Permalink to &quot;Manus 与 Meta 分拆后首轮融资超 5 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-08">2026-10-08</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/a8a7da90f9a9.jpg" alt="配图"></p><p>Manus 完成与 Meta 分拆后的首轮融资，金额超过 5 亿美元，由博裕资本与 IDG 资本领投，腾讯、HSG（原红杉中国）、真格基金等老股东跟投。这轮融资显示中国 AI Agent 赛道在资本层面依然活跃，也意味着 Manus 将独立推进产品与商业化。对读者：关注其后续 Agent 产品定价与开放策略，判断是否值得纳入团队工具链评估。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/08/chinas-manus-raises-over-500m-in-first-funding-round-since-split-with-meta/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="nous-research-确认-15-亿美元估值-推出面向企业的-ai-agent" tabindex="-1">Nous Research 确认 15 亿美元估值，推出面向企业的 AI Agent <a class="header-anchor" href="#nous-research-确认-15-亿美元估值-推出面向企业的-ai-agent" aria-label="Permalink to &quot;Nous Research 确认 15 亿美元估值，推出面向企业的 AI Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-08">2026-10-08</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/7ed6bc016168.jpg" alt="配图"></p><p>Hermes Agent 开发商 Nous Research 完成 9000 万美元 B 轮融资，估值达 15 亿美元，并同步推出面向企业用户的 AI Agent 产品。开源模型背景的团队转向企业级 Agent 商业化，是今年开源与商业边界模糊化的又一案例。对读者：若团队已在用 Hermes 系列模型，可跟进其企业版能力与许可条款变化。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/07/nous-research-confirms-it-hit-1-5b-valuation-launches-ai-agents-for-business-users/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="tristan-harris-的科技非营利组织大幅裁员-转向-创始人主导" tabindex="-1">Tristan Harris 的科技非营利组织大幅裁员，转向“创始人主导” <a class="header-anchor" href="#tristan-harris-的科技非营利组织大幅裁员-转向-创始人主导" aria-label="Permalink to &quot;Tristan Harris 的科技非营利组织大幅裁员，转向“创始人主导”&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Wired AI</span><time datetime="2026-10-08">2026-10-08</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/74493528e85b.jpg" alt="配图"></p><p>曾推动“反过度屏幕时间”运动的 Center for Humane Technology 将裁撤大部分员工，转为创始人主导模式。报道称内部在方向与策略上的张力已持续多年。科技伦理倡导组织在 AI 高速扩张期面临定位与资金双重压力。对读者：关注 AI 伦理与监管议题时，需留意倡导机构本身的影响力变化。</p><p class="news-entry-source"><a href="https://www.wired.com/story/tristan-harris-tech-nonprofit-is-laying-off-most-staff-and-going-founder-led/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="claude-上线-dashboards-与-motion-docs-slides-design-转正全量开放" tabindex="-1">Claude 上线 Dashboards 与 Motion，Docs/Slides/Design 转正全量开放 <a class="header-anchor" href="#claude-上线-dashboards-与-motion-docs-slides-design-转正全量开放" aria-label="Permalink to &quot;Claude 上线 Dashboards 与 Motion，Docs/Slides/Design 转正全量开放&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-10-08">2026-10-08</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/b83ce0d4b6e8.webp" alt="配图"></p><p>Anthropic 为 Claude 推出两项 beta 功能：Claude Dashboards 用于构建实时数据看板，Claude Motion 用于生成动画讲解内容。同时 Docs、Slides、Design 结束 beta，向包括免费版在内的所有 Claude 套餐开放。这意味着 Claude 正从对话助手向办公与可视化生产工具延伸。对读者：若团队已订阅 Claude，可先试用 Dashboards 替代部分轻量 BI 场景。</p><p class="news-entry-source"><a href="https://claude.com/resources/articles/dashboards-and-motion" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="google-推出跨应用-通用-gemini-agent" tabindex="-1">Google 推出跨应用“通用”Gemini Agent <a class="header-anchor" href="#google-推出跨应用-通用-gemini-agent" aria-label="Permalink to &quot;Google 推出跨应用“通用”Gemini Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-10-08">2026-10-08</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/4b64eb63bd22.png" alt="配图"></p><p>Google 在 Gemini at Work 活动上发布通用 Gemini Agent，可在后台跨应用与设备执行任务，入口位于 Gemini Enterprise，支持 Gmail、Drive、Docs、Sheets、Calendar 以及 Slack、Microsoft 365 等第三方应用，并可从移动端、桌面与网页调用。云端运行意味着任务可持续执行。对读者：企业评估 Agent 平台时，可把跨应用权限与审计能力作为核心对比项。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/1007904/google-gemini-ai-agent-enterprise" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="chatgpt-上线-intelligent-ui-回答中直接嵌入图表与按钮" tabindex="-1">ChatGPT 上线“Intelligent UI”，回答中直接嵌入图表与按钮 <a class="header-anchor" href="#chatgpt-上线-intelligent-ui-回答中直接嵌入图表与按钮" aria-label="Permalink to &quot;ChatGPT 上线“Intelligent UI”，回答中直接嵌入图表与按钮&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-10-08">2026-10-08</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/73a004626f04.png" alt="配图"></p><p>OpenAI 随 GPT-6 向所有用户推送 Intelligent UI，ChatGPT 可在文本回答中生成图表、示意图、表单与可点击按钮等交互元素。官方称已训练 GPT-6 判断何时用可视化替代纯文本。聊天界面正从纯文本输出转向可交互的轻应用形态。对读者：做前端集成时需提前考虑这类富交互输出的渲染与可访问性适配。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/1007276/openai-chatgpt-intelligent-ui-gpt-6" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="google-推出完全离线的-ai-会议记录应用-ai-edge-foresight" tabindex="-1">Google 推出完全离线的 AI 会议记录应用 AI Edge Foresight <a class="header-anchor" href="#google-推出完全离线的-ai-会议记录应用-ai-edge-foresight" aria-label="Permalink to &quot;Google 推出完全离线的 AI 会议记录应用 AI Edge Foresight&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-10-08">2026-10-08</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/ab7e2f48b443.jpg" alt="配图"></p><p>Google 发布实验性笔记应用 AI Edge Foresight，可在完全离线状态下转写会议与音频文件，基于端侧 EmbeddingGemma 2 模型运行于 macOS，免费使用。用户记录要点后，应用会结合转写内容整理成“润色后的笔记”，对标 Granola、Wispr Flow。对读者：对数据敏感的场景可优先评估端侧方案，但需确认离线模型的准确率是否达标。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/1007985/google-ai-notetaking-app-transcribe-offline" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="anthropic-发布-claude-haiku-5-5-1m-上下文-输入每百万-token-仅-0-10-美元" tabindex="-1">Anthropic 发布 Claude Haiku 5.5：1M 上下文，输入每百万 token 仅 0.10 美元 <a class="header-anchor" href="#anthropic-发布-claude-haiku-5-5-1m-上下文-输入每百万-token-仅-0-10-美元" aria-label="Permalink to &quot;Anthropic 发布 Claude Haiku 5.5：1M 上下文，输入每百万 token 仅 0.10 美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-08">2026-10-08</time></p><p>Anthropic 推出小模型 Claude Haiku 5.5，保留 1M 上下文，输入价格低至每百万 token 0.10 美元，在 OSWorld 上得分 72.4%。相比 Haiku 4.5 的 1 美元输入价，降幅约九成，直接对标 OpenAI GPT-6 Luna 的定价。对读者：高频、成本敏感的批处理与子 Agent 场景可优先切换到 Haiku 5.5 做成本压测。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/07/anthropic-releases-claude-haiku-5-5-a-small-model-with-1m-context-priced-at-0-10-per-million-input-tokens/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="perplexity-发布-pplx-embed-v2-late-0-6b-端侧与-9b-索引双版本" tabindex="-1">Perplexity 发布 pplx-embed-v2-late：0.6B 端侧与 9B 索引双版本 <a class="header-anchor" href="#perplexity-发布-pplx-embed-v2-late-0-6b-端侧与-9b-索引双版本" aria-label="Permalink to &quot;Perplexity 发布 pplx-embed-v2-late：0.6B 端侧与 9B 索引双版本&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-08">2026-10-08</time></p><p>Perplexity 推出 pplx-embed-v2-late 嵌入模型，包含面向边缘设备的 0.6B 版本和用于高质量索引构建的 9B 版本，MADQA 最高得分 92.4%，ViDoRe v3 Markdown 最低 61.2%。两个版本均为 MIT 许可，可自行部署。对读者：自建 RAG 的团队可将其纳入嵌入模型候选，注意不同任务上的分数差异较大。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/07/perplexity-ai-releases-pplx-embed-v2-late-a-0-6b-edge-model-and-a-9b-model-scoring-92-4-on-madqa/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="liquid-ai-开源-d1-3b-与-d1-omni-600m-多模态决策模型" tabindex="-1">Liquid AI 开源 d1-3B 与 d1-omni-600M 多模态决策模型 <a class="header-anchor" href="#liquid-ai-开源-d1-3b-与-d1-omni-600m-多模态决策模型" aria-label="Permalink to &quot;Liquid AI 开源 d1-3B 与 d1-omni-600M 多模态决策模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-08">2026-10-08</time></p><p>Liquid AI 发布 Open d1 系列两个开放权重多模态模型：d1-3B 可读文本与图像，d1-omni-600M 支持文本配图像或音频。两者均不输出文本，而是在单次前向传播中返回校准后的类型化答案，输出 token 为零，面向实时决策场景。对读者：分类、判定类任务可尝试用决策模型替代生成式模型以降低延迟与成本。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/07/liquid-ai-releases-open-weight-d1-3b-and-d1-omni-600m-multimodal-decision-models-with-zero-output-tokens/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="unsloth-studio-在运行前重新校验模型仓库变更" tabindex="-1">Unsloth Studio 在运行前重新校验模型仓库变更 <a class="header-anchor" href="#unsloth-studio-在运行前重新校验模型仓库变更" aria-label="Permalink to &quot;Unsloth Studio 在运行前重新校验模型仓库变更&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-08">2026-10-08</time></p><p>Unsloth 发布 10 月 6 日安全说明，介绍 Studio 在运行前如何检查代码、权重、依赖包与工具：自定义模型代码会被扫描且审批绑定到指纹，被标记的权重文件在加载路径中被拦截，包内容问题会导致 CI 失败，工具运行在探测过的操作系统沙箱中。对读者：本地跑第三方模型权重时，可参考这套校验点设计自己的加载前检查流程。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/07/what-happens-when-a-trusted-model-repo-changes-unsloth-studio-re-checks-before-it-runs/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="stack-overflow-给编码-agent-一套-操作系统-式的纪律化构建方法" tabindex="-1">Stack Overflow：给编码 Agent 一套“操作系统”式的纪律化构建方法 <a class="header-anchor" href="#stack-overflow-给编码-agent-一套-操作系统-式的纪律化构建方法" aria-label="Permalink to &quot;Stack Overflow：给编码 Agent 一套“操作系统”式的纪律化构建方法&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Stack Overflow Blog</span><time datetime="2026-10-08">2026-10-08</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/20f7ba6660cd.png" alt="配图"></p><p>Stack Overflow 博客 Part 6 讨论编码 Agent 的长期质量问题：Agent 适合干一下午，却难以稳定支撑一个季度。文章给出少量文件与规则配置，用于在数月、上千次编辑中防止质量衰减，适用于单 Agent 或同仓库多 Agent 并行。对读者：若团队已把编码 Agent 纳入日常流程，可先落地这套配置模板再谈规模化。</p><p class="news-entry-source"><a href="https://stackoverflow.blog/2026/10/07/part-6-an-operating-system-for-coding-agents-the-disciplined-build/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div>',8)])])}const g=a(r,[["render",i]]);export{m as __pageData,g as default};
